const PRIORITIES = ['low', 'normal', 'high'];
let counter = 0;

export async function listTools() {
  return [
    {
      name: 'ticket_create',
      description: 'Create a support ticket.',
      inputSchema: {
        type: 'object',
        properties: {
          title: { type: 'string', description: 'Short summary of the issue.' },
          description: { type: 'string', description: 'Detailed description of the issue.' },
          priority: { type: 'string', enum: PRIORITIES, description: 'Ticket priority.' },
        },
        required: ['title', 'description'],
        additionalProperties: false,
      },
    },
  ];
}

function fail(message) {
  throw new Error(message);
}

export async function callTool(name, args = {}) {
  if (name !== 'ticket_create') {
    fail(`Unknown tool: ${name}`);
  }

  if (typeof args !== 'object' || args === null || Array.isArray(args)) {
    fail('Arguments must be an object');
  }

  const { title, description, priority } = args;

  if (typeof title !== 'string' || title.trim() === '') {
    fail('title must be a non-empty string');
  }
  if (typeof description !== 'string' || description.trim() === '') {
    fail('description must be a non-empty string');
  }
  if (priority !== undefined && !PRIORITIES.includes(priority)) {
    fail(`priority must be one of ${PRIORITIES.join(', ')}`);
  }

  const allowed = ['title', 'description', 'priority'];
  for (const key of Object.keys(args)) {
    if (!allowed.includes(key)) {
      fail(`Unknown argument: ${key}`);
    }
  }

  const finalPriority = priority === undefined ? 'normal' : priority;
  counter += 1;
  const id = `t${counter}`;

  return {
    content: [
      { type: 'text', text: `Created ticket ${id}: ${title} (priority: ${finalPriority})` },
    ],
  };
}

